1	import { Hono } from "hono";
2	import type { Db } from "@paperclipai/db";
3	
4	/**
5	 * Local copies of the HTTP handler types from `server/src/http/types.ts`.
6	 *
7	 * We duplicate rather than import because the server package uses Node-only
8	 * modules (`node:stream`, etc.) and cannot be bundled into a Worker. These
9	 * shapes must remain structurally identical to the upstream definitions.
10	 * When upstream types change, update these in lock-step.
11	 *
12	 * TODO: extract `server/src/http/types.ts` into a separate `@paperclipai/http`
13	 * package with zero Node dependencies so both the server and CF Worker can
14	 * import it directly (tracked in PR #6).
15	 */
16	export interface ActorContext {
17	  type: "board" | "agent";
18	  userId?: string;
19	  agentId?: string;
20	  companyId?: string;
21	}
22	
23	export interface RequestCtx {
24	  method: string;
25	  url: URL;
26	  headers: Headers;
27	  json<T = unknown>(): Promise<T>;
28	  text(): Promise<string>;
29	  param(name: string): string | undefined;
30	  query(name: string): string | undefined;
31	  actor: ActorContext | null;
32	  db: Db;
33	  storage: StorageServiceLike;
34	}
35	
36	export type Handler = (ctx: RequestCtx) => Promise<Response>;
37	
38	export interface RouteDefinition {
39	  method: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
40	  /** Express/Hono-style path, e.g. `/api/companies/:companyId`. */
41	  path: string;
42	  handler: Handler;
43	}
44	
45	/**
46	 * Minimal shape of the storage service dependency.
47	 * We use a structural alias to avoid importing the server's Node-typed
48	 * `StorageService` directly.
49	 */
50	export interface StorageServiceLike {
51	  provider: string;
52	  putFile(input: unknown): Promise<unknown>;
53	  getObject(companyId: string, objectKey: string): Promise<unknown>;
54	  headObject(companyId: string, objectKey: string): Promise<unknown>;
55	  deleteObject(companyId: string, objectKey: string): Promise<void>;
56	}
57	
58	export interface MountRoutesOptions {
59	  db: Db;
60	  storage: StorageServiceLike;
61	  /**
62	   * Optional middleware that populates `ctx.actor` from the request.
63	   * Called before the route handler for every matched route.
64	   *
65	   * Return `null` to treat the request as unauthenticated.
66	   * Throw or return a `Response` to short-circuit with an error.
67	   */
68	  resolveActor?: (request: Request) => Promise<ActorContext | null>;
69	}
70	
71	/**
72	 * Mounts an array of `RouteDefinition` objects onto a Hono app.
73	 *
74	 * Each route definition is a transport-agnostic handler (from the
75	 * `server/src/http/types.ts` seam). This function bridges from the Hono
76	 * request context to the `RequestCtx` shape those handlers expect.
77	 *
78	 * Usage:
79	 * ```ts
80	 * import { Hono } from "hono";
81	 * import { mountRoutes } from "./hono-adapter.js";
82	 * import { myRoutes } from "../../server/src/routes/my-routes.js";
83	 *
84	 * const app = new Hono();
85	 * mountRoutes(app, myRoutes, { db, storage });
86	 * ```
87	 */
88	export function mountRoutes(
89	  app: Hono,
90	  routes: RouteDefinition[],
91	  options: MountRoutesOptions,
92	): void {
93	  const { db, storage, resolveActor } = options;
94	
95	  for (const route of routes) {
96	    const method = route.method.toLowerCase() as "get" | "post" | "put" | "patch" | "delete";
97	
98	    app[method](route.path, async (c) => {
99	      // Resolve actor from request (auth middleware equivalent)
100	      const actor = resolveActor ? await resolveActor(c.req.raw) : null;
101	
102	      const ctx: RequestCtx = {
103	        method: c.req.method,
104	        url: new URL(c.req.url),
105	        headers: new Headers(c.req.raw.headers),
106	
107	        async json<T>(): Promise<T> {
108	          return c.req.json<T>();
109	        },
110	
111	        async text(): Promise<string> {
112	          return c.req.text();
113	        },
114	
115	        param(name: string): string | undefined {
116	          return c.req.param(name);
117	        },
118	
119	        query(name: string): string | undefined {
120	          return c.req.query(name);
121	        },
122	
123	        actor,
124	        db,
125	        storage,
126	      };
127	
128	      try {
129	        return await route.handler(ctx);
130	      } catch (err) {
131	        // Unhandled errors become 500s. In production, Cloudflare's Worker
132	        // error logging captures the stack trace.
133	        console.error(
134	          `[HonoAdapter] Unhandled error in ${route.method} ${route.path}: ${
135	            err instanceof Error ? err.stack ?? err.message : String(err)
136	          }`,
137	        );
138	        return c.json({ error: "Internal Server Error" }, 500);
139	      }
140	    });
141	  }
142	}
